884	/// The account feature's one write call (`account-settings-update`) — the
885	/// only `/account/settings` endpoint (Boundaries: "no GET endpoint exists").
886	/// Posts via the shared `ApiClient`, mirroring
887	/// `auth_remote_data_source.dart`'s pattern.
888	class AccountRemoteDataSource {
889	  AccountRemoteDataSource(this._apiClient);
890	
891	  final ApiClient _apiClient;
892	
893	  /// Called with `{}` to read the current settings without changing
894	  /// anything (Boundaries: "`PATCH /account/settings` ... called empty to
895	  /// read").
896	  Future<Either<Failure, AccountSettingsDto>> fetchSettings() =>
897	      _patch(const {});
898	
899	  /// Called with exactly `{"biometricEnabled": enabled}` to write — never
900	  /// `displayName`/`persona` (Epic 8's scope, Boundaries).
901	  Future<Either<Failure, AccountSettingsDto>> updateBiometricEnabled(
902	    bool enabled,
903	  ) => _patch({'biometricEnabled': enabled});
904	
905	  Future<Either<Failure, AccountSettingsDto>> _patch(
906	    Map<String, dynamic> data,
907	  ) async {
908	    final result = await _apiClient.patch(
909	      'account-settings-update',
910	      data: data,
911	    );
912	    return result.flatMap((json) {
913	      try {
914	        final responseData = json['data'] as Map<String, dynamic>;
915	        return right(AccountSettingsDto.fromJson(responseData));
916	      } catch (error) {
917	        // A 200 response that doesn't match the expected shape is a
918	        // client-side parse failure, never a backend-sent code — maps to
919	        // the local-only `malformedResponse` (RNF09: no exception escapes).
920	        return left(Failure.malformedResponse(message: error.toString()));
921	      }
922	    });
923	  }
924	}
