963	/// Owns the one broadcast `biometricEnabled` stream Story 2.4's AD-14-style
964	/// seam requires. Covers the I/O & Edge-Case Matrix exactly:
965	/// - boot fetch resolves `false`/`true` -> [currentBiometricEnabled]/
966	///   [biometricEnabledStream] updated to that value.
967	/// - boot fetch fails -> swallowed, [currentBiometricEnabled] unchanged.
968	/// - [setBiometricEnabled] -> flips immediately (optimistic), PATCH fires;
969	///   success leaves it flipped, failure reverts it and returns `Left`.
970	class AccountSettingsRepositoryImpl implements AccountSettingsRepository {
971	  AccountSettingsRepositoryImpl({
972	    required AccountRemoteDataSource remoteDataSource,
973	  }) : _remoteDataSource = remoteDataSource;
974	
975	  final AccountRemoteDataSource _remoteDataSource;
976	  final StreamController<bool> _controller = StreamController<bool>.broadcast();
977	
978	  /// Starts `true` (never `null`, Boundaries) — the single source of truth
979	  /// for both the vault gate and the Configurações toggle.
980	  bool _currentValue = true;
981	
982	  @override
983	  bool get currentBiometricEnabled => _currentValue;
984	
985	  @override
986	  Stream<bool> get biometricEnabledStream {
987	    // Same `Stream.multi` replay-to-late-listeners rationale as
988	    // `VaultRepositoryImpl.statusStream`/`SessionRepositoryImpl.
989	    // statusStream`: a listener that subscribes after construction still
990	    // immediately sees the cached current value rather than nothing until
991	    // the next emission.
992	    return Stream<bool>.multi((controller) {
993	      controller.add(_currentValue);
994	      final subscription = _controller.stream.listen(
995	        controller.add,
996	        onError: controller.addError,
997	        onDone: controller.close,
998	      );
999	      controller.onCancel = subscription.cancel;
1000	    }, isBroadcast: true);
1001	  }
1002	
1003	  void _emit(bool value) {
1004	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
1005	    // an in-flight `fetchBiometricEnabled()`/`setBiometricEnabled()` call —
1006	    // mirrors `VaultRepositoryImpl._emit`'s own guard.
1007	    if (_controller.isClosed) {
1008	      return;
1009	    }
1010	    _currentValue = value;
1011	    _controller.add(value);
1012	  }
1013	
1014	  @override
1015	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async {
1016	    final result = await _remoteDataSource.fetchSettings();
1017	    return result.match((failure) {
1018	      // Swallowed, fire-and-forget like `SessionRepository.
1019	      // restoreSession()` — `currentBiometricEnabled` stays exactly as it
1020	      // was (I/O matrix: "Boot fetch fails").
1021	      return left(failure);
1022	    }, (dto) {
1023	      _emit(dto.biometricEnabled);
1024	      return right(unit);
1025	    });
1026	  }
1027	
1028	  @override
1029	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
1030	    final previous = _currentValue;
1031	    // Optimistic flip — switches immediately, before the PATCH call below
1032	    // even starts (RNF01, <100ms; Boundaries).
1033	    _emit(enabled);
1034	    final result = await _remoteDataSource.updateBiometricEnabled(enabled);
1035	    return result.match((failure) {
1036	      // Revert on failure — the caller surfaces `failure.message` inline.
1037	      _emit(previous);
1038	      return left(failure);
1039	    }, (_) => right(unit));
1040	  }
1041	
1042	  @override
1043	  Future<void> dispose() async {
1044	    await _controller.close();
1045	  }
