1120	  /// own stream by the time this is shown (I/O matrix: "Toggle fails ->
1121	  /// switch reverts ... Failure.message shown inline").
1122	  final String? errorMessage;
1123	
1124	  AccountSettingsState copyWith({
1125	    bool? biometricEnabled,
1126	    String? errorMessage,
1127	    bool clearErrorMessage = false,
1128	  }) {
1129	    return AccountSettingsState(
1130	      biometricEnabled: biometricEnabled ?? this.biometricEnabled,
1131	      errorMessage: clearErrorMessage
1132	          ? null
1133	          : (errorMessage ?? this.errorMessage),
1134	    );
1135	  }
