1161	class AccountSettingsCubit extends Cubit<AccountSettingsState> {
1162	  AccountSettingsCubit(this._repository)
1163	    : super(
1164	        AccountSettingsState(
1165	          biometricEnabled: _repository.currentBiometricEnabled,
1166	        ),
1167	      ) {
1168	    _subscription = _repository.biometricEnabledStream.listen(
1169	      (value) => emit(state.copyWith(biometricEnabled: value)),
1170	    );
1171	  }
