1174	  late final StreamSubscription<bool> _subscription;
1175	
1176	  Future<void> toggleBiometric(bool value) async {
1177	    emit(state.copyWith(clearErrorMessage: true));
1178	    final result = await _repository.setBiometricEnabled(value);
1179	    result.match(
1180	      (failure) => emit(state.copyWith(errorMessage: failure.message)),
1181	      (_) {},
1182	    );
1183	  }
